contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We record balance before, call c.go sending amount, and assert that owner didn't change
    // and that our contract's balance did not decrease by more than the sent amount (so no extra theft).
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient funds to send");

        address ownerBefore = c.owner();
        uint balBefore = address(this).balance;

        bool reverted;
        // call c.go with value = amount
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();
        uint balAfter = address(this).balance;

        // General rule: c.owner never changes, and if the call did not revert then our balance
        // must be >= balBefore - amount (we shouldn't lose more than the sent amount).
        // If the call reverted, our balance must be == balBefore (no funds moved).
        assert(
            ownerBefore == ownerAfter
            && (reverted ? (balAfter == balBefore) : (balAfter + amount >= balBefore))
        );
    }

    receive() external payable {}
}

