contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an arbitrary amount to send to c.go. The function is payable so the checker
    // can provide Ether to this test contract and choose amount.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Read owner and balance before the call
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(this).balance;
        uint256 cBalanceBefore = address(c).balance;

        // Call c.go forwarding amount and capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read owner and c.balance after
        address ownerAfter = c.owner();
        uint256 cBalanceAfter = address(c).balance;
        uint256 balanceAfter = address(this).balance;

        // General property:
        // - owner is never changed
        // - if call did not revert then c's balance becomes zero
        // - whether reverted or not, the tester's balance never drops by more than amount
        assert(ownerBefore == ownerAfter && (
            reverted || cBalanceAfter == 0
        ) && (balanceBefore - balanceAfter <= amount));
    }

    receive() external payable {}
}
